head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//발행기관 상세정보
scwin.vScrenID = "ULDINS91600.xml";
scwin.param1 = "";
scwin.param2 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 상세정보
 ***********************************************/
scwin.ins_search = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS91600_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.readCorpInfoView" + "&{P}param01=" + txb_pISUR_CD.getValue();
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS91600_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.readCorpInfoInquiry" + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    //ShowWin(grd_Grid); // 그리드명을 표기 

};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    //	CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    //CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.gform_onload = function() {
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(panel_5, false);
    $c.stf.showObj(panel_6, false);
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_4);
    //PanelToGroupBox(panel_5);   
    //PanelToGroupBox(panel_6);   


    txb_pISUR_CD.focus();
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(scwin.arrPar);
        scwin.param1 = ((scwin.arrPar.length >= 1) && (scwin.arrPar[0] != undefined) ? scwin.arrPar[0] : "");
        txb_pISUR_CD.setValue(scwin.param1);
        scwin.param2 = ((scwin.arrPar.length >= 1) && (scwin.arrPar[1] != undefined) ? scwin.arrPar[1] : "");
        txb_pISUR_NM.setValue(scwin.param2);
        scwin.ins_search();
    }
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_detail_OnLoadCompleted = function(rowcount) {

};
scwin.dts_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_detail);
};
scwin.img_COM_NM_onclick = function() {
    ins_popupOpen(txb_pISUR_CD, txb_pISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.btn_file_onclick = function() {
    /*
    txb_param1 에는 신청ID
    txb_param2 에는 구분값을 넣는데.. 
    			 + "1 : 발행기관신청, 팩스-발행기관신청 \n"
    			 + "2 : 표준코드신청, 팩스-표준코드신청 \n"
    			 + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
    			 */
    txb_param1.setValue(txb_ISUR_CD.getValue());
    txb_param2.setValue("1");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};
scwin.txb_pISUR_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.txb_COM_NM_onclick = function() {
    txb_param1.setValue(txb_ISUR_CD.getValue());
    txb_param2.setValue("");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91800", "발행기관 회사명변경 현황 상세정보", "880", "260");
};
scwin.txb_HPAGE_onclick = function() {
    if (txb_HPAGE.getValue() == "") return;
    var url = "http://" + txb_HPAGE.getValue();
    window.open(url, "", "scrollbars=yes,toolbar=no,resizable=yes,left=0,top=0");
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (row == 0) return;
    var KND = dts_List.getCellData(row, "KIND");
    var STD_CD = dts_List.getCellData(row, "STD_CD");
    //alert("KND   " +KND  + "	STD_CD "+STD_CD  );
    if (KND == "지표" || KND == "선물옵션" || KND == "스트립") {
        txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    } else {
        txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    }
    fn_GetPar = fn_GetParam;
    ins_ViewIsuMaster(KND, STD_CD);
};
